	})
	if err != nil {
		t.Fatalf("WriteCommitted() error = %v", err)
	}

	compactContent, ok := readBranchFile(t, store, cpID.Path()+"/0/"+paths.CompactTranscriptFileName)
	if !ok {
		t.Fatal("transcript.jsonl missing from checkpoint tree")
